import React from "react";
import {Html5Audio, Sequence, staticFile, useVideoConfig} from "remotion";

/**
 * The bundled CC0 sound-effect pack (public/sfx/, generated by the kit, no
 * third-party audio). Every file is already normalised to about −20 LUFS
 * (`sfxTargetLUFS`), so every gain is 1.0; change a gain only after listening.
 */
export type SfxId = "whoosh" | "pop" | "tick" | "boom" | "ding" | "riser" | "glitch" | "drop";

export const SFX: Record<SfxId, {src: string; seconds: number; gain: number; use: string}> = {
  whoosh: {src: "sfx/whoosh.mp3", seconds: 0.85, gain: 1, use: "a scene change or a big camera move"},
  pop: {src: "sfx/pop.mp3", seconds: 0.23, gain: 1, use: "a text, chip or number appears"},
  tick: {src: "sfx/tick.mp3", seconds: 0.11, gain: 1, use: "counting: one tick per counted item"},
  boom: {src: "sfx/boom.mp3", seconds: 1.65, gain: 1, use: "the turn: the one moment the story flips"},
  ding: {src: "sfx/ding.mp3", seconds: 1.65, gain: 1, use: "the payoff or the answer lands"},
  riser: {src: "sfx/riser.mp3", seconds: 2.05, gain: 1, use: "build tension just before a reveal (ends on the reveal word)"},
  glitch: {src: "sfx/glitch.mp3", seconds: 0.65, gain: 1, use: "an error, a wrong idea, a myth on screen"},
  drop: {src: "sfx/drop.mp3", seconds: 0.5, gain: 1, use: "disappointment, a fail, a number that falls"},
};

/**
 * Base level for every effect, multiplied by the file's gain. 0.7 ≈ −3 dB under
 * the voice, chosen by listening: level with the voice pulls the video toward
 * a meme video.
 */
export const SFX_VOLUME = 0.7;

/** Story/horror effects (synthesised in-house, no licence strings): id → file + length. */
/** Story/horror effects — real recordings (Pixabay Content License), trimmed + normalised in public/sfx/story/. */
export const STORY_SFX: Record<string, {src: string; seconds: number; use: string}> = {
  stinger: {src: "sfx/story/stinger.mp3", seconds: 2.9, use: "jump scare hit"},
  footsteps: {src: "sfx/story/footsteps.mp3", seconds: 5, use: "footsteps on a wooden floor"},
  knock: {src: "sfx/story/knock.mp3", seconds: 1.8, use: "knocking on a wooden door"},
  creak: {src: "sfx/story/creak.mp3", seconds: 3.1, use: "a door creaking open"},
  scream: {src: "sfx/story/scream.mp3", seconds: 3, use: "a woman screaming"},
  howl: {src: "sfx/story/howl.mp3", seconds: 6, use: "a dog/wolf howling at night"},
  owl: {src: "sfx/story/owl.mp3", seconds: 3.7, use: "an owl hooting in the dark"},
  bell: {src: "sfx/story/bell.mp3", seconds: 8, use: "a temple bell ringing far away"},
  whisper: {src: "sfx/story/whisper.mp3", seconds: 3.1, use: "a creepy whisper"},
  heartbeat: {src: "sfx/story/heartbeat.mp3", seconds: 6, use: "a pounding heart"},
  thud: {src: "sfx/story/thud.mp3", seconds: 0.9, use: "a body or object falling"},
};

/** Story cues from sfx.json: in a pause they play at line end, otherwise at line start, a bit louder than accents. */
export const storySfxCues = (
  items: readonly {line: number; id: string; pause?: number}[],
  lines: readonly {start: number; end: number}[],
  fps: number,
): SfxCue[] =>
  items
    .filter((it) => STORY_SFX[it.id] && lines[it.line])
    .map((it) => ({
      at: Math.round(((it.pause ?? 0) > 0 ? lines[it.line].end + 0.12 : lines[it.line].start) * fps),
      src: STORY_SFX[it.id].src,
      volume: (it.pause ?? 0) > 0 ? 1 : 0.55,
    }));

/**
 * A cue: a bundled effect by `id`, or your own file under public/ by `src`.
 * `at` is an absolute frame; get it from `frameAtWord`, never type it by hand.
 */
export type SfxCue = {at: number; id?: SfxId; src?: string; volume?: number};

/**
 * Sound effects as accents (§8): at most `sfxMaxPerVideo` per video. Render
 * at the composition root (ShortsTemplate does), not inside a scene Sequence,
 * so an effect on a scene boundary is not cut off.
 */
export const Sfx: React.FC<{cues: readonly SfxCue[]}> = ({cues}) => {
  const {fps} = useVideoConfig();
  return (
    <>
      {cues.map((c, i) => {
        const entry = c.id ? SFX[c.id] : undefined;
        const src = entry?.src ?? c.src;
        if (!src) throw new Error(`Sfx cue #${i + 1} at frame ${c.at} has neither id nor src.`);
        return (
          <Sequence
            key={`${src}-${c.at}-${i}`}
            from={Math.max(0, Math.round(c.at))}
            durationInFrames={entry ? Math.ceil(entry.seconds * fps) : undefined}
            name={`sfx ${c.id ?? src}`}
          >
            <Html5Audio src={staticFile(src)} volume={SFX_VOLUME * (entry?.gain ?? 1) * (c.volume ?? 1)} />
          </Sequence>
        );
      })}
    </>
  );
};
